class AutoType(object):
    """Auto specifier type, used to indicate that a spec should be
    auto-generated from context (e.g., using the dict key as the spec)."""
    def __repr__(self):
        return 'Auto'

    def glomit(self, target, scope):
        return target


Auto = AutoType()


class Fill(object):
    """Fill specifier type, used to fill in default values for missing keys.

    Fill takes a dict spec, and when glommed, fills in missing keys
    with their default values.
    """
    def __init__(self, spec):
        self.spec = spec

    def __repr__(self):
        cn = self.__class__.__name__
        return '%s(%r)' % (cn, self.spec)

    def glomit(self, target, scope):
        return scope[glom](target, self.spec, scope)


class Iter(object):
    """Iter specifier type, used to iterate over the target.

    Iter can take an optional subspec to apply to each element.
    """
    def __init__(self, spec=None):
        self.spec = spec

    def __repr__(self):
        cn = self.__class__.__name__
        if self.spec is not None:
            return '%s(%r)' % (cn, self.spec)
        return '%s()' % (cn,)

    def glomit(self, target, scope):
        iterate = scope[TargetRegistry].get_handler('iterate', target, path=scope[Path])
        iterator = iterate(target)
        ret = []
        for item in iterator:
            if self.spec is not None:
                val = scope[glom](item, self.spec, scope)
            else:
                val = item
            ret.append(val)
        return ret


class Let(object):
    """Let specifier type, used to bind variables in the scope.

    Let takes keyword arguments and binds them in the scope for
    use by subspecs.
    """
    def __init__(self, **kwargs):
        self._bindings = kwargs

    def __repr__(self):
        cn = self.__class__.__name__
        args = ', '.join('%s=%r' % (k, v) for k, v in self._bindings.items())
        return '%s(%s)' % (cn, args)

    def glomit(self, target, scope):
        scope.update(self._bindings)
        return target


class ROOTType(object):
    """ROOT sentinel type, used to refer to the root target."""
    def __repr__(self):
        return 'ROOT'

    def glomit(self, target, scope):
        # Find the original root target from the scope chain
        # The root is the target at the outermost scope
        return scope[Spec]


ROOT = ROOTType()


class Invoke(object):
    """Invoke specifier type, similar to Call but with constants instead of args/kwargs.

    Invoke takes a callable and a dict of constants to pass as keyword arguments.
    """
    def __init__(self, func, constants=None):
        if not callable(func):
            raise TypeError('expected func to be a callable, not: %r' % (func,))
        self.func = func
        if constants is None:
            constants = {}
        self.constants = constants

    def __repr__(self):
        cn = self.__class__.__name__
        return '%s(%r, constants=%r)' % (cn, self.func, self.constants)

    def glomit(self, target, scope):
        kwargs = {}
        for name, val in self.constants.items():
            kwargs[name] = val
        return self.func(target, **kwargs)
